class Solution:
    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def f(s):
            c = min(s)
            return s.count(c)
        wf = [f(w) for w in words]
        return [sum(fq < x for x in wf) for fq in map(f, queries)]

