var numSmallerByFrequency = function(queries, words) {
    const f = s => {
        const cnt = Array(26).fill(0);
        for (const ch of s) cnt[ch.charCodeAt(0) - 97]++;
        for (let i = 0; i < 26; i++) if (cnt[i]) return cnt[i];
        return 0;
    };
    const wf = words.map(f).sort((a, b) => a - b);
    const upperBound = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= x) lo = mid + 1; else hi = mid;
        }
        return lo;
    };
    return queries.map(q => wf.length - upperBound(wf, f(q)));
};

